<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\{Folio,Guest,Reservation,ReservationRoom,Room,RoomType}; use Carbon\Carbon; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class ReservationController extends Controller { public function index(Request $request){ return Reservation::with(['guest','rooms.room','rooms.roomType'])->where('property_id',$request->user()->property_id)->latest()->paginate(25); } public function store(Request $request){ $d=$request->validate(['property_id'=>['nullable','exists:properties,id'],'guest.first_name'=>['required','string','max:120'],'guest.last_name'=>['nullable','string','max:120'],'guest.phone'=>['nullable','string','max:50'],'guest.email'=>['nullable','email'],'check_in'=>['required','date'],'check_out'=>['required','date','after:check_in'],'adults'=>['required','integer','min:1'],'children'=>['nullable','integer','min:0'],'room_type_id'=>['required','exists:room_types,id'],'room_id'=>['nullable','exists:rooms,id'],'rate_plan_id'=>['nullable','exists:rate_plans,id'],'nightly_rate'=>['nullable','numeric','min:0'],'source'=>['nullable','string','max:50'],'special_requests'=>['nullable','string']]); return DB::transaction(function() use($d,$request){ $propertyId=(int)$request->user()->property_id; abort_unless($propertyId,422,'Your account is not assigned to a hotel property.'); $guest=Guest::create(array_merge($d['guest'],['property_id'=>$propertyId])); $in=Carbon::parse($d['check_in']); $out=Carbon::parse($d['check_out']); $nights=max(1,$in->copy()->startOfDay()->diffInDays($out->copy()->startOfDay())); $roomType=RoomType::findOrFail($d['room_type_id']); $rate=(float)($d['nightly_rate'] ?? $roomType->base_rate); if(!empty($d['room_id'])){ $conflict=ReservationRoom::where('room_id',$d['room_id'])->whereHas('reservation',fn($q)=>$q->whereIn('status',['pending','confirmed','checked_in']))->where('check_in_at','<',$out)->where('check_out_at','>',$in)->exists(); abort_if($conflict,422,'Selected room is not available for these dates.'); } $total=$rate*$nights; $reservation=Reservation::create(['property_id'=>$propertyId,'guest_id'=>$guest->id,'reference'=>config('hms.reservation_prefix','RES').'-'.now()->format('ymd').'-'.strtoupper(Str::random(6)),'status'=>'confirmed','source'=>$d['source']??'front_desk','check_in_at'=>$in,'check_out_at'=>$out,'adults'=>$d['adults'],'children'=>$d['children']??0,'subtotal'=>$total,'grand_total'=>$total,'special_requests'=>$d['special_requests']??null,'created_by'=>$request->user()?->id]); ReservationRoom::create(['reservation_id'=>$reservation->id,'room_id'=>$d['room_id']??null,'room_type_id'=>$roomType->id,'rate_plan_id'=>$d['rate_plan_id']??null,'nightly_rate'=>$rate,'adults'=>$d['adults'],'children'=>$d['children']??0,'check_in_at'=>$in,'check_out_at'=>$out]); Folio::create(['property_id'=>$propertyId,'guest_id'=>$guest->id,'reservation_id'=>$reservation->id,'folio_number'=>config('hms.folio_prefix','FOL').'-'.now()->format('ymd').'-'.strtoupper(Str::random(6)),'status'=>'open','balance'=>0]); return response()->json(['data'=>$reservation->load(['guest','rooms.roomType','folio'])],201); }); } }
